from lib import *
S = SS('x70')
steps = [
    step("先看三个位置属性。工作目录里有 ./config/application.properties(app.name=cwd-config,另有只在这里出现的 only.cwd),classpath 里有 application.properties(app.name=classpath,另有 only.classpath),还有一个 ./custom/ 目录。什么都不设:app.name 是 cwd-config,only.classpath 和 only.cwd 都读得到。-Dspring.config.location=file:./custom/ 是「替换」默认位置:app.name 变成 custom,only.classpath 和 only.cwd 都变成 null,默认位置整个不读了。-Dspring.config.additional-location=file:./custom/ 是「追加」:app.name 还是 custom(追加的在默认位置之上),only.classpath 和 only.cwd 仍然读得到。-Dspring.config.name=other 只换文件名,位置不变:读 config/other.properties,app.name 是 cwd-config-other,application.properties 里独有的 key 全读不到。location 可以直接写到文件(file:./custom/other.properties → other),多个位置用逗号分隔,后面的优先:classpath:/,file:./custom/ 得到 custom,顺序反过来得到 classpath。两个容易踩的坑:目录末尾少一个斜杠(file:./custom),启动抛出 IllegalStateException「File extension is not known to any PropertySourceLoader. If the location is meant to reference a directory, it must end in '/'」;目录不存在又没加 optional:,报「Config data location 'file:./nope/' does not exist」,Action 提示加 optional: 前缀,加上之后启动正常、app.name 是 null。", t=tl(S(1)), mark=lidx(S(1), '替换默认位置', '目录末尾没有斜杠', '目录不存在,没写'), done=lidx(S(1), '不设置(默认位置)', '追加在默认位置之上', '多个位置用逗号', '顺序反过来', 'optional:file:./nope/'), b=bars([['默认位置下能读到的 key 个数(数出来的)', 3, '3'], ['location 替换后能读到的 key 个数', 1, '1'], ['additional-location 追加后能读到的 key 个数', 3, '3'], ['spring.config.name=other 后能读到的 key 个数', 1, '1']], 3, done=[0, 2], mark=[1, 3]), kv=KV([['location', '替换默认位置'], ['additional-location', '追加,在默认位置之上'], ['name', '只换文件名,位置不变'], ['目录', '必须以 / 结尾;不存在要加 optional:']], ['location'])),
    step("spring.config.import 的优先级。application.properties 里写 app.name=main 和 x=from-main,并 import 一个也写了 app.name 的文件:app.name 是 imported,x 还是 from-main——被导入的文件覆盖声明它的文件,没覆盖的 key 照旧来自原文件。一行 import 两个文件(imp.properties、imp2.properties):app.name 是 imported2,顺序反过来是 imported,后面的赢。被导入的文件还能再 import(a import b):app.name 是 b,x 来自 b,链上越靠后越优先。命令行 --spring.config.import=file:./imp.properties 也能导入,同样赢过 application.properties 里的 main;但命令行再给 --app.name=cmdline,就是 cmdline(来源 commandLineArgs)赢过导入的文件。classpath:imp.properties 也能导入,app.name 是 cp-imp。被导入的文件不存在时:没写 optional: 启动失败,报「Config data resource 'file [missing.properties]' via location 'file:./missing.properties' does not exist」,还附上了这个 import 的来源位置 [file:application.properties] - 1:22;写成 optional:file:./missing.properties 就正常启动,app.name 是 main。", t=tl(S(2)), mark=lidx(S(2), '不存在,没写 optional', '链式', '命令行又写'), done=lidx(S(2), '自己写 app.name=main', '同一行 import 两个文件', '顺序反过来', '写了 optional', '--spring.config.import', 'classpath:)'), b=bars([['链式 import:app.name 来自第几层(main=1,a=2,b=3)', 3, '3(b)'], ['一行 import 两个文件:赢的是第几个', 2, '2(imp2)'], ['import 的文件不存在、没写 optional:(1=启动失败)', 1, '失败'], ['同上,写了 optional:(0=正常启动)', 0, '正常']], 3, done=[0, 1, 3], mark=[2]), kv=KV([['imported vs 声明者', '被导入的赢,没覆盖的 key 照旧'], ['多个 import', '后面的赢'], ['命令行 --app.name', '仍然高于被导入的文件'], ['不存在的文件', '要加 optional: 才不报错']], ['imported vs 声明者'])),
    step("没有扩展名的文件与 configtree:。import 一个叫 secret 的文件,不指定格式,启动失败,同样是「File extension is not known to any PropertySourceLoader」;写成 file:./secret[.properties] 就按 properties 读,db.password 是 s3cret;写成 [.yaml] 就按 YAML 读,db:password: 的值 yaml-secret 读成 db.password。configtree:./tree/ 是 Kubernetes 把 Secret / ConfigMap 挂成「一个 key 一个文件」时用的形式:目录里的文件名是 key,文件内容是 value,子目录用来表示点号(tree/app/name 读成 app.name,值 from-tree),来源名是 Config tree。文件末尾的换行:内容 \"abc\\n\" 读出来长度 3(换行被去掉),\"abc\\n\\n\" 长度 5(两个换行都保留),\" abc \" 长度 5(空格保留),\"abc\" 长度 3。读 Boot 4.0.8 的 ConfigTreePropertySource 源码:这个选项只在内容以换行结尾、并且整段内容里只有一个换行时才去掉那一个换行。configtree 目录不存在又没写 optional: 同样启动失败,Description 里写着 config tree 和 does not exist。", t=tl(S(3)), mark=lidx(S(3), '不指定格式', 'configtree 的目录不存在'), done=lidx(S(3), '[.properties]', '[.yaml]', 'configtree:./tree/', '换行、空格'), b=bars([['\"abc\\n\" 读出的长度', 3, '3'], ['\"abc\\n\\n\" 读出的长度', 5, '5'], ['\" abc \" 读出的长度', 5, '5'], ['\"abc\" 读出的长度', 3, '3']], 5, done=[0, 3], mark=[1, 2]), kv=KV([['没有扩展名', '要写 [.properties] 或 [.yaml]'], ['configtree:', '文件名是 key,内容是 value'], ['末尾换行', '只有一个换行时才去掉'], ['目录不存在', '要加 optional:']], ['末尾换行'])),
    step("多个文档放在同一个文件里。application.properties 用 #--- 分成 4 个文档:第 1 个 app.name=base、x=base;第 2 个 on-profile=dev、app.name=dev;第 3 个 on-profile=prod、app.name=prod、x=prod;第 4 个只有 y=last。不激活 profile:app.name 是 base,x 是 base,y 是 last;激活 dev:app.name 是 dev,x 还是 base;激活 prod:app.name 是 prod,x 是 prod,y 都是 last。文档顺序有意义:把 on-profile=dev 的文档写在前面、没有 profile 条件的普通文档写在后面,激活 dev 后 app.name 是 plain-after,后面的普通文档把 dev 盖掉了。application.yaml 用 --- 分文档,激活 dev 得到 yaml-dev;application.properties 和 application.yaml 同时写 app.name,读到的是 props,properties 高于 yaml。on-profile=dev 的文档里写了 spring.profiles.active=prod:不激活 dev 时这个文档不生效(app.name 还是 base),active profiles 却变成了 [prod],没有报错;加 --spring.profiles.active=dev 时 active profiles 是 [dev]。我没有追到为什么。application-dev.properties 这种 profile 专属「文件」里写 spring.profiles.active 就明确不行,启动抛出 InvalidConfigDataPropertyException:「Property 'spring.profiles.active' imported from location 'file [application-dev.properties]' is invalid in a profile specific resource」。on-profile=dev 的文档里写 spring.config.import 可以:激活 dev 时导入,app.name 是 imported-by-dev;不激活时不导入,app.name 是 base。", t=tl(S(4)), mark=lidx(S(4), 'profile 专属的文档写在前面', '第二个文档 on-profile=dev 里写了', 'application-dev.properties 里写'), done=lidx(S(4), '分成 4 个文档,profile dev', '分成 4 个文档,profile prod', 'application.yaml(--- 分文档)', '同时存在,都写 app.name', 'spring.config.import,激活 dev'), b=bars([['dev:app.name 来自第几个文档', 2, '2'], ['prod:app.name 来自第几个文档', 3, '3'], ['profile 文档在前、普通文档在后:赢的是第几个文档', 2, '2(plain-after)'], ['4 个文档里 y=last 所在的文档', 4, '4']], 4, done=[0, 1, 3], mark=[2]), kv=KV([['文档顺序', '后面的盖掉前面的,不管有没有 profile 条件'], ['properties vs yaml', 'properties 高于 yaml'], ['profile 专属文件里的 spring.profiles.active', '启动抛 InvalidConfigDataPropertyException'], ['on-profile 文档里的 import', '只在该 profile 激活时才导入']], ['文档顺序'])),
    step("默认位置的最终顺序。先看一个全部加在一起的例子:classpath 有 application.properties、config/application.properties,工作目录有 application.properties(顺带 import imp.properties)、config/application.properties、config/sub1/、config/sub2/ 下的 application.properties。不激活 profile,Environment 里 7 个来源从高到低是:file:config/sub2、file:config/sub1、file:config/、imp.properties、file:application.properties、classpath:config/、classpath:根——config/*/ 里按目录名排,sub2 高于 sub1;被 import 的 imp.properties 只比声明它的 file:application.properties 高一位,仍然低于 file:config/ 下的文件。激活 dev 后多出的 application-dev.properties 排第 1 位,app.name 是 cwd-dev,也高于 imp.properties。再把同一个 dev 文件分别只放在 5 个位置(其余位置各有一个不带 profile 的 application.properties,共 6 个来源):放在 classpath:/ 或 classpath:/config/,dev 文件都排第 4 位,上面是 3 个 file: 下的普通文件,app.name 是 sub1;放在 file:./、file:./config/ 或 file:./config/sub1/,dev 文件都排第 1 位,高于其他全部 5 个来源。也就是说默认位置分成两组:classpath 一组、file 一组(源码里 DEFAULT_SEARCH_LOCATIONS 是 \"optional:classpath:/;optional:classpath:/config/\" 和 \"optional:file:./;optional:file:./config/;optional:file:./config/*/\" 两项);同一组里 profile 专属的文件整体高于不带 profile 的文件,不同的组之间 file 整组高于 classpath 整组。", t=tl(S(5)), mark=lidx(S(5), '激活 dev(多了', 'classpath:/:', 'classpath:/config/:'), done=lidx(S(5), '不激活 profile,Environment', 'file:./:', 'file:./config/:', 'file:./config/sub1/:'), b=bars([['dev 文件放在 classpath:/ 时排第几', 4, '4'], ['dev 文件放在 classpath:/config/ 时排第几', 4, '4'], ['dev 文件放在 file:./ 时排第几', 1, '1'], ['dev 文件放在 file:./config/ 时排第几', 1, '1'], ['dev 文件放在 file:./config/sub1/ 时排第几', 1, '1']], 6, done=[2, 3, 4], mark=[0, 1]), kv=KV([['两组', 'classpath 一组,file 一组'], ['组内', 'profile 专属的文件整体高于普通文件'], ['组间', 'file 整组高于 classpath 整组'], ['import', '只比声明它的文件高一位']], ['两组'])),
]
